portaria:{name:'Portaria',icon:'flag',point:[815,555],entry:[815,555],crop:[713,459,280,200],text:'Chegada ao Solaris e início da sua jornada. A portaria interna fica junto ao setor de lazer, distinta do acesso externo.'},
