{id:'azul',name:'Roupa azul',icon:'shirt',kind:'outfit',cost:80,unlock:3,color:'#5485a0',desc:'Um visual azul para o personagem no mapa.'},
{id:'ipe',name:'Ipê do jardim',icon:'tree',kind:'decor',cost:140,unlock:3,desc:'Um ipê florido para dar cor ao seu refúgio virtual.'},
{id:'banco',name:'Banco de madeira',icon:'bench',kind:'decor',cost:80,unlock:3,desc:'Um lugar de pausa na paisagem do seu refúgio.'},
{id:'flores',name:'Canteiro florido',icon:'flower',kind:'decor',cost:60,unlock:3,desc:'Um canteiro que dá um toque de cor ao jardim.'},
{id:'cafe',name:'Cantinho do café',icon:'cup',kind:'decor',cost:120,unlock:6,desc:'Mesa e café para compor um encontro no seu refúgio.'},
{id:'lagoa',name:'Pequena lagoa',icon:'water',kind:'decor',cost:180,unlock:6,desc:'Uma pequena lâmina d’água na paisagem virtual.'},
{id:'arvore',name:'Árvore de sombra',icon:'tree',kind:'decor',cost:100,unlock:3,desc:'Uma copa generosa para seu cantinho de natureza.'},
{id:'luz',name:'Luz do jardim',icon:'sun',kind:'decor',cost:80,unlock:9,desc:'Um ponto de luz dourada para o seu jardim.'},
{id:'piquenique',name:'Piquenique',icon:'heart',kind:'decor',cost:100,unlock:6,desc:'Uma composição de piquenique para a paisagem do jogo.'},
{id:'coral',name:'Roupa coral',icon:'shirt',kind:'outfit',cost:80,unlock:9,color:'#b66f67',desc:'Um visual coral para suas novas explorações.'},
{id:'jardim',name:'Jardim ornamental',icon:'leaf',kind:'decor',cost:140,unlock:9,desc:'Um conjunto de folhagens para dar volume visual ao jardim, sem alterar o masterplan.'}
