const GLYPHS=['leaf','flower','bird','heart','water','camera','sun','tree'];
const NAMES={leaf:'Folha',flower:'Flor',bird:'Pássaro',heart:'Coração',water:'Água',camera:'Câmera',sun:'Sol',tree:'Árvore'};
function fresh(){return{v:2,started:false,name:'',best:Array(15).fill(0),attempts:Array(15).fill(0),claimed:[],purchases:[],outfit:'terra',transport:'walk',slots:Array(6).fill(null),visited:[],node:0};}
function sanitize(raw){if(!raw||raw.v!==2||!Array.isArray(raw.best)||raw.best.length!==15)throw Error('Passaporte incompatível.');const s=fresh();s.visited=[...new Set(Array.isArray(raw.visited)?raw.visited:[])].filter(id=>typeof id==='string'&&Object.hasOwn(VISITS,id));s.started=raw.started===true;s.name=typeof raw.name==='string'?raw.name.slice(0,24):'';s.best=raw.best.map(n=>Number.isInteger(n)?clamp(n,0,3):0);let gap=false;s.best=s.best.map(n=>{if(gap)return 0;if(!n)gap=true;return n;});s.attempts=s.best.map((_,i)=>Number.isInteger(raw.attempts?.[i])?clamp(raw.attempts[i],0,99999):0);s.claimed=[...new Set(Array.isArray(raw.claimed)?raw.claimed:[])].filter(id=>{const t=ITEMS.find(t=>t.id===id);return t?.chapter&&s.best.slice(0,t.chapter*3).every(Boolean);});let budget=s.best.reduce((n,v)=>n+(v?60+20*v:0),0)+visitCoins(s.visited);s.purchases=[...new Set(Array.isArray(raw.purchases)?raw.purchases:[])].filter(id=>{const t=ITEMS.find(t=>t.id===id);if(!t?.cost||s.best.filter(Boolean).length<t.unlock||budget<t.cost)return false;budget-=t.cost;return true;});const owned=[...s.claimed,...s.purchases,...(s.visited.length===9?EXTRA:[])];s.outfit=raw.outfit==='terra'||owned.includes(raw.outfit)&&ITEMS.find(t=>t.id===raw.outfit)?.kind==='outfit'?raw.outfit:'terra';s.transport=['bike','horse'].includes(raw.transport)&&owned.includes(raw.transport)?raw.transport:'walk';const used=new Set();s.slots=s.slots.map((_,i)=>{const id=raw.slots?.[i];if(!owned.includes(id)||ITEMS.find(t=>t.id===id)?.kind!=='decor'||used.has(id))return null;used.add(id);return id;});s.node=Number.isInteger(raw.node)&&raw.node>=0&&raw.node<window.SolarisPaths.nodes.length?raw.node:0;return s;}
let state=fresh(),persistent=true,ready=false,currentView='journey',chapter=0,selectedDecor=null;
try{const r=localStorage.getItem(KEY);if(r)state=sanitize(JSON.parse(r));else{const old=JSON.parse(localStorage.getItem(OLDKEY)||'null');if(typeof old?.nickname==='string')state.name=old.nickname.slice(0,24);}}catch(e){persistent=false;}
const completed=()=>state.best.filter(Boolean).length,stars=()=>state.best.reduce((a,b)=>a+b,0),earned=()=>completed()*60+stars()*20+visitCoins(state.visited),spent=()=>state.purchases.reduce((a,id)=>a+(ITEMS.find(t=>t.id===id)?.cost||0),0),coins=()=>earned()-spent(),xp=()=>completed()*75+stars()*25+visitXP(state.visited),rank=()=>Math.min(10,Math.floor(xp()/250)+1),owned=id=>state.claimed.includes(id)||state.purchases.includes(id)||(state.visited.length===9&&EXTRA.includes(id));
const available=id=>id===1||state.best[id-2]>0,chapterDone=c=>state.best.slice(c*3,c*3+3).every(Boolean),eligible=t=>t.exploration?state.visited.length===9:t.chapter?chapterDone(t.chapter-1):completed()>=t.unlock;
const starmark=n=>`<span class="stars" aria-label="${n} de 3 estrelas">${[1,2,3].map(i=>svg('star',i<=n?'lit':'')).join('')}</span>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));persistent=true;}catch(e){persistent=false;}$('storageNote').textContent=persistent?'As conquistas ficam neste navegador. Exporte uma cópia para guardar ou importar em outro aparelho. Não há ranking oficial nem validação de prêmios físicos.':'O armazenamento está indisponível: progresso apenas nesta sessão. Exporte seu passaporte antes de sair. Não há sincronização nem ranking oficial.';}
function notice(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('toast').hidden=true,3300);}
function showDialog(id){$('visitToast').hidden=true;sound?.setWalking(false);const d=$(id);if(!d.open)d.showModal();}
function update(){const c=completed(),s=stars();$('stars').textContent=s;$('coins').textContent=coins();$('rank').textContent=(state.name?state.name+' · ':'EXPLORADOR · ')+'NÍVEL '+rank();$('xp').textContent=xp()+' XP';$('xpBar').style.width=(rank()===10?100:(xp()%250)/250*100)+'%';$('done').textContent=c;$('journeyIntro').textContent=c===15?'Jornada concluída. Volte às fases para conquistar as 45 estrelas.':`${c} de 15 fases concluídas · ${s} de 45 estrelas.`;$('rewardDot').hidden=!ITEMS.some(t=>t.chapter&&eligible(t)&&!owned(t.id));$('app').dataset.completed=c;$('app').dataset.stars=s;$('app').dataset.coins=coins();renderJourney();renderRewards();renderRefuge();renderPassport();renderTransport();applyOutfit();renderExploration();}
function switchView(view){if(!['journey','mapView','rewards','refuge','passport'].includes(view))return;$('visitToast').hidden=true;currentView=view;sound?.setWalking(view==='mapView'&&route.length>0&&!paused,state.transport);sound?.setScene(view==='mapView'?(targetArea||'praca'):view==='refuge'?'refuge':'praca');document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==view);document.querySelectorAll('#bottomNav [data-view]').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});$('app').dataset.view=view;if(view==='mapView')requestAnimationFrame(()=>{resizeMap();if(!mapSeen){mapSeen=true;overviewMap();}});if(view==='refuge')renderRefuge();if(view==='passport')renderPassport();}
function renderJourney(){const c=completed();$('chapterCount').textContent=`Capítulo ${chapter+1} de 5`;$('chapters').innerHTML=CHAPTERS.map((ch,i)=>`<button class="chapter-tab" data-chapter="${i}" aria-selected="${i===chapter}" aria-label="Capítulo ${i+1}: ${ch.title}">${svg(chapterDone(i)?'check':i>0&&!chapterDone(i-1)?'lock':ch.icon)}<b><span class="chapter-tab-word">Cap. </span>${i+1}</b></button>`).join('');$('chapterLabel').textContent='CAPÍTULO '+String(chapter+1).padStart(2,'0');$('chapterTitle').textContent=CHAPTERS[chapter].title;$('chapterDescription').textContent=CHAPTERS[chapter].description;$('levels').innerHTML=LEVELS.slice(chapter*3,chapter*3+3).map(l=>{const r=regions[l.area],locked=!available(l.id),n=state.best[l.id-1];return `<button class="level" data-level="${l.id}" ${locked?'disabled':''} aria-label="Fase ${l.id}: ${l.name}, ${n} estrelas${locked?', bloqueada':''}"><div class="level-thumb" style="--pos:${r.point[0]/14.48}% ${r.point[1]/10.86}%"><span class="level-no">FASE ${String(l.id).padStart(2,'0')}</span>${svg(locked?'lock':l.icon)}</div><div class="level-body"><small>${r.name}</small><h3>${l.name}</h3><div class="level-bottom">${starmark(n)}<span>${locked?'Bloqueada':n?'Rejogar':'Jogar →'}</span></div></div></button>`;}).join('');const t=ITEMS.find(t=>t.id===CHAPTERS[chapter].prize),claimed=owned(t.id),a=eligible(t);$('chapterPrize').innerHTML=`<div class="reward-icon">${svg(t.icon)}</div><div><h3>${t.name}</h3><p>${claimed?'Conquista resgatada':a?'Capítulo concluído. Seu prêmio está liberado.':`Conclua as fases ${chapter*3+1} a ${chapter*3+3}.`}</p></div><button class="${a&&!claimed?'primary':'secondary'}" data-item="${t.id}">${claimed?'Ver item':a?'Resgatar':'Ver prêmio'}</button>`;const next=ITEMS.find(t=>t.chapter&&!owned(t.id))||ITEMS.find(t=>t.id==='varanda');$('nextRewardIcon').innerHTML=svg(next.icon);$('nextRewardName').textContent=owned(next.id)?'Sua jornada, completa.':next.name;$('nextRewardText').textContent=owned(next.id)?`${45-stars()} estrelas ainda podem ser conquistadas. Aproveite seu refúgio.`:eligible(next)?'Prêmio liberado. Visite a vitrine e resgate sua conquista.':`Complete o capítulo ${next.chapter} para liberar. Faltam ${Math.max(0,next.chapter*3-c)} fases.`;$('continueJourney').innerHTML=(c===15?'Aperfeiçoar minhas estrelas':'Continuar jornada')+svg('arrow');}
$('chapters').onclick=e=>{const b=e.target.closest('[data-chapter]');if(b){chapter=Number(b.dataset.chapter);renderJourney();}};
$('levels').onclick=e=>{const b=e.target.closest('[data-level]');if(b)brief(Number(b.dataset.level));};
$('continueJourney').onclick=()=>{const id=state.best.findIndex(n=>!n);if(id>=0)brief(id+1);else{const j=state.best.findIndex(n=>n<3);if(j>=0){chapter=Math.floor(j/3);brief(j+1);}else switchView('refuge');}};
function renderRewards(){$('milestones').innerHTML=ITEMS.filter(t=>t.chapter).map(t=>`<article class="milestone ${owned(t.id)?'claimed':eligible(t)?'available':''}"><div class="reward-emblem">${svg(t.icon)}</div><small>CAPÍTULO ${t.chapter} · PRÊMIO VIRTUAL</small><h3>${t.name}</h3><p>${owned(t.id)?'Já faz parte da sua coleção.':eligible(t)?'Conquistado. Pronto para resgatar.':`Conclua as ${t.chapter*3} primeiras fases.`}</p><button class="${eligible(t)&&!owned(t.id)?'primary':'secondary'}" data-item="${t.id}">${owned(t.id)?'Na coleção':eligible(t)?'Resgatar prêmio':'Conhecer prêmio'}</button></article>`).join('');$('storeBalance').innerHTML=`${coins()} Sóis`;$('store').innerHTML=ITEMS.filter(t=>t.cost).map(t=>`<button class="store-item" data-item="${t.id}"><div class="item-art" ${t.color?`style="color:${t.color}"`:''}>${svg(t.icon)}</div><div><h3>${t.name}</h3><p>${t.kind==='decor'?'Seu refúgio virtual':'Seu personagem'}</p><span class="price">${svg(owned(t.id)?'check':eligible(t)?'sun':'lock')}${owned(t.id)?'Na coleção':eligible(t)?t.cost+' Sóis':'Após '+t.unlock+' fases'}</span></div></button>`).join('');}
let inspecting=null;
function inspectItem(id){const t=ITEMS.find(t=>t.id===id);if(!t)return;inspecting=t;$('rewardArt').innerHTML=svg(t.icon);$('rewardTitle').textContent=t.name;$('rewardDescription').textContent=t.desc;const has=owned(id),unlock=eligible(t);$('rewardPrice').textContent=t.exploration?(has?'Coleção completa · recompensa automática':'Visite os nove locais para conquistar'):has?'Já está na sua coleção':!unlock?`Libera após concluir ${t.chapter?t.chapter*3:t.unlock} fases`:t.cost?t.cost+' Sóis virtuais · saldo '+coins():'Prêmio de capítulo · sem custo';$('rewardClaim').textContent=has?t.kind==='vehicle'?'Usar no mapa':t.kind==='frame'?'Ver meu passaporte':'Usar no refúgio':t.cost?'Trocar Sóis por este item':'Resgatar minha conquista';$('rewardClaim').disabled=!has&&(!unlock||t.cost>coins());showDialog('rewardDialog');}
['milestones','store','chapterPrize','explorationAwards'].forEach(id=>$(id).onclick=e=>{const b=e.target.closest('[data-item]');if(b)inspectItem(b.dataset.item);});
$('rewardClaim').onclick=()=>{const t=inspecting;if(!t)return;if(!owned(t.id)){if(!eligible(t)||t.cost>coins()){notice('Esta conquista ainda não está disponível.');return;}if(t.chapter)state.claimed.push(t.id);else state.purchases.push(t.id);save();update();playCue('reward');notice(t.name+' adicionado à coleção.');}if(t.kind==='outfit')state.outfit=t.id;if(t.kind==='vehicle')state.transport=t.id;if(t.kind==='decor')selectedDecor=t.id;save();applyOutfit();renderTransport();$('rewardDialog').close();switchView(t.kind==='vehicle'?'mapView':t.kind==='frame'?'passport':'refuge');};
function applyOutfit(){const color=ITEMS.find(t=>t.id===state.outfit)?.color||'#bf7854';document.documentElement.style.setProperty('--shirt',color);$('vehicle').innerHTML=state.transport==='walk'?'':svg(state.transport==='bike'?'bike':'horse');$('player').classList.toggle('mounted',state.transport!=='walk');}
