function trailConfig(size){if(size===5)return{rows:['..###','#...#','..#.#','.##.#','.....'],start:0,end:24};return{rows:['...###','.#...#','...#.#','##.#..','...##.','......'],start:0,end:35};}
function trailPath(rows,start,end){const n=rows.length,q=[[start]],seen=new Set([start]);while(q.length){const p=q.shift(),i=p.at(-1);if(i===end)return p;for(const j of [i-n,i+n,i-1,i+1])if(j>=0&&j<n*n&&Math.abs(j%n-i%n)+Math.abs(Math.floor(j/n)-Math.floor(i/n))===1&&rows[Math.floor(j/n)][j%n]!=='#'&&!seen.has(j)){seen.add(j);q.push([...p,j]);}}return [];}
