function buildPrecision(l){let value=0,shots=0,misses=0,raf=0,start=performance.now(),slow=false,closed=false,cooldown=false,timer=0;$('missionBoard').innerHTML='<div class="precision-court"><i class="court-ball" id="courtBall"></i></div><div class="precision-meter"><div class="precision-zone" id="precisionZone"></div><i class="precision-needle" id="needle"></i></div><div class="shot-dots" id="shotDots"><span></span><span></span><span></span></div>';const shoot=action('Lançar na zona dourada',()=>{if(cooldown||closed||shots>=3)return;const aim=tapValue===null?value:tapValue;tapValue=null;cooldown=true;timer=setTimeout(()=>{cooldown=false;shoot.disabled=false;},450);shoot.disabled=true;if(Math.abs(aim-.5)<(slow?.18:.1)){shots++;playCue('hit');$('courtBall').classList.remove('hit');void $('courtBall').offsetWidth;$('courtBall').classList.add('hit');}else{misses++;playCue('error');}[...$('shotDots').children].forEach((e,i)=>e.classList.toggle('hit',i<shots));status(`${shots}/3 acertos · ${misses} erros`);if(shots===3){clearTimeout(timer);cancelAnimationFrame(raf);shoot.disabled=false;shoot.textContent='Guardar desempenho';shoot.onclick=()=>finishEngine(misses===0?3:misses<=3?2:1,`Três acertos com ${misses} erros.`);}},'primary','shoot');let tapValue=null;shoot.addEventListener('pointerdown',()=>{tapValue=value;});shoot.addEventListener('pointercancel',()=>{tapValue=null;});function tick(t){if(closed)return;const period=slow?5200:3100;value=(Math.sin((t-start)/period*Math.PI*2-Math.PI/2)+1)/2;$('needle').style.left=value*100+'%';$('needle').dataset.value=value.toFixed(4);if(shots<3)raf=requestAnimationFrame(tick);}hintEngine=()=>{slow=true;$('precisionZone').style.left='32%';$('precisionZone').style.width='36%';status('Modo tranquilo: indicador mais lento e zona maior. Máximo 2★.');};cleanupEngine=()=>{closed=true;cancelAnimationFrame(raf);clearTimeout(timer);};status('Toque quando o indicador entrar na faixa dourada.');raf=requestAnimationFrame(tick);}
